import java.util.*;

class Solution {
  private List<Integer>[] g;
  private Set<Long> guesses;
  private int k;

  private long key(int a, int b) {
    return ((long) a << 32) | (b & 0xffffffffL);
  }

  private int dfs(int u, int p) {
    int s = guesses.contains(key(p, u)) ? 1 : 0;
    for (int v : g[u]) if (v != p) s += dfs(v, u);
    return s;
  }

  private int reroot(int u, int p, int score) {
    int ans = score >= k ? 1 : 0;
    for (int v : g[u])
      if (v != p) {
        int ns =
            score - (guesses.contains(key(u, v)) ? 1 : 0) + (guesses.contains(key(v, u)) ? 1 : 0);
        ans += reroot(v, u, ns);
      }
    return ans;
  }

  public int rootCount(int[][] edges, int[][] guesses, int k) {
    int n = edges.length + 1;
    this.k = k;
    g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    this.guesses = new HashSet<>();
    for (int[] x : guesses) this.guesses.add(key(x[0], x[1]));
    return reroot(0, -1, dfs(0, -1));
  }
}
